INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (241206,0,0,'That tree they felled--that''s what caused Suncrown''s destruction! The Amani will pay for this!',12,0,100,0,0,300074,0,285929,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (241205,0,0,'Lor''themar, we found evidence of a nearby hideout--',12,0,100,0,0,300077,0,290511,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,0,0,'This is the place--covered in runes and well warded, it seems.',12,0,100,0,0,300086,0,285071,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,0,1,'If they were this well guarded, we''ll want to take care ahead. Follow me, and keep quiet.',12,0,100,0,0,300088,0,285072,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (236610,1,0,'I suspect the Amani didn''t want any uninvited guests. Lucky these wards are old.',12,0,100,0,0,300087,0,285073,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (237344,0,0,'Keep back!',12,0,100,0,0,0,0,0,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (237344,0,1,'Protect the lightwood!',12,0,100,0,0,0,0,0,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (237344,0,2,'You wish to die?',12,0,100,0,0,0,0,0,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (237344,0,3,'Zul''jan! The enemy is here!',12,0,100,0,0,0,0,0,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (237344,0,4,'This is ours!',12,0,100,0,0,0,0,0,0,'retail quote (Wowhead)');
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,SoundPlayType,BroadcastTextId,TextRange,comment) VALUES (237344,1,0,'We cannot... falter...',12,0,100,0,0,0,0,0,0,'retail quote (Wowhead)');
